import{installTouchZoomGuard}from'./touch-controls.js';
import{fleetPreview,SYSTEMS,moduleAccess,LAUNCH_COLOURS,localDay,createLaunchCheck,scoreLaunchCheck,hasLaunchProof,ensureFleet,rocketPlan,rocketStatus,rocketDeck,recordRocket,launchRocket,validConstruction,mixedCheck,markCheck,ENCOUNTERS,encounterAt}from'./rockets.js';
import{rocketArt,planetArt,starsArt}from'./space-art.js';
import{bindOrbitDrawing,bindRowBuilder}from'./hands-on.js';
import{mountMeteorDash,mountConstellation,GAMES,availableGames,mountBonusGame}from'./starbase.js';
import {nextCosmoPraise,resumeCosmo,bookmarkCosmo,newState,cleanTables,focusKey,focusLabel,factsFor,deckFor,MODES,BADGES,badgeCount,confirmIdentity,changeTables,recordPractice,lights,greenCount,answerOutcome,createRun,nextRunFact,scoreHop,chooseFeature,claimClothes,buyItem,equipItem,resetMission} from './learning.js';
import {ITEMS,SHOP,EYE_COLOURS,wardrobeItems,weeklyReward,claimWeeklySuit,grantRainbowSuit} from './wardrobe.js';
import {palMarkup,mountMonsters,COLOURS} from './monster.js';
import {bindPalInteractions,setSound,soundEffect,setCharacterVoice} from './pal-interaction.js';
import {say,sayFact,stopVoice,soundEnabled,unlockVoice} from './audio.js';
installTouchZoomGuard();
const KEY='multiploids-prototype-v1',$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state.version!==1||!state.profiles?.length)state=null;}catch{}state??=newState();for(const pr of state.profiles){ensureFleet(pr);if(badgeCount(pr)>=6)pr.rainbowUnlocked=true;grantRainbowSuit(pr);}state.spaceVersion=2;
let renderedDay=localDay(),fleetExpanded=false;
let flight=null,launchTimer=null,launchInterval=null,arcadeMode=null,cleanArcade=null,cleanManip=null,orbitEditor=null,activeReadTable=null,readToken=0;
let view='home',session=null,tablePicker=false,modal=null,draft={},feedback='',cleanModels=null,cleanGestures=null,advanceTimer=null,noticeTimer=null,offlineReady=location.protocol==='capacitor:';
const p=()=>state.profiles[state.active]||state.profiles[0];
function save(){if(badgeCount(p())>=6)p().rainbowUnlocked=true;grantRainbowSuit(p());try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('This browser cannot save progress right now.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
const icon=(key)=>({skyhop:'↟',cargo:'▦',bridge:'⋯',power:'ϟ',star:'✦',spark:'✧',home:'⌂',moon:'☾'}[key]||'✧');
function creature(profile=p(),extra=''){const key=JSON.stringify([profile.species,profile.colour,profile.antennae,profile.eyeColour,profile.wearing,profile.voiceStyle]);return `<div class="live-creature ${extra}" data-creature-key="${esc(key)}">${palMarkup(profile)}</div>`;}
function skyArt(){return `<svg class="sky-art" viewBox="0 0 800 550" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#cedfe9"/><stop offset="1" stop-color="#e5efde"/></linearGradient><linearGradient id="rock" x2="0" y2="1"><stop stop-color="#91b8a4"/><stop offset="1" stop-color="#bdd1b9"/></linearGradient></defs><path fill="url(#sky)" d="M0 0h800v550H0z"/><circle cx="666" cy="96" r="53" fill="#fff0c6" opacity=".85"/><g fill="#f5f8f1" opacity=".85"><path d="M38 124c-17-38 28-63 53-42 23-45 81-27 81 9 36-10 53 37 14 42H51z"/><path d="M528 239c-21-35 20-61 45-43 22-40 76-22 76 14 37-8 47 32 15 36H544z"/><path d="M634 421c-12-29 20-49 40-32 24-34 63-19 63 8 30-7 43 28 14 32H645z"/></g><g stroke="#94b4b9" stroke-width="3" stroke-dasharray="5 12" fill="none" opacity=".5"><path d="M180 445Q260 256 429 306T620 108"/></g><g fill="url(#rock)"><path d="m90 444 111-13 78 19-32 20-94 6z"/><path d="m347 303 86-10 71 15-26 18-79 5z"/><path d="m545 154 90-13 62 15-27 18-72 4z"/></g><g fill="#f0e6c8"><ellipse cx="185" cy="444" rx="98" ry="14"/><ellipse cx="425" cy="303" rx="79" ry="12"/><ellipse cx="620" cy="153" rx="78" ry="12"/></g><g fill="#698b7c"><ellipse cx="182" cy="440" rx="77" ry="8"/><ellipse cx="425" cy="300" rx="64" ry="7"/><ellipse cx="620" cy="150" rx="62" ry="7"/></g><g fill="#dfb95c"><path d="m318 181 5 12 13 2-10 8 3 13-11-7-11 7 3-13-10-8 13-2z"/><path d="m516 65 4 10 11 1-9 7 3 11-9-6-10 6 3-11-8-7 11-1z"/></g><path d="M625 135V78" stroke="#6b778a" stroke-width="3"/><path d="m626 78 34 8-34 17z" fill="#c69fce"/><g fill="#728b94" opacity=".7"><path d="m62 250 10-6 10 6-10-2z"/><path d="m456 116 9-6 9 6-9-2z"/></g></svg>`;}
function header(){return `<header class="app-header"><a href="#" data-go="home" class="brand"><img src="logo.svg" alt=""><span>multiploids<small>little numbers. a universe of adventure.</small></span></a><nav aria-label="Main navigation">${[['home','Mission Control'],['workshop','Your Multiploid'],['progress','My progress'],['starbase','The Starbase']].map(([id,label])=>`<button class="nav-link ${view===id?'active':''}" data-go="${id}">${label}</button>`).join('')}</nav><div class="header-tools"><button id="sound" class="icon-button" aria-label="${state.sound?'Mute':'Enable'} sounds">${state.sound?'♫':'♫̸'}</button><select id="profile" aria-label="Choose explorer">${state.profiles.map((pr,i)=>`<option value="${i}" ${state.active===i?'selected':''}>${esc(pr.name)}</option>`).join('')}</select><button data-go="grownups" class="grownups">Grown-ups ↗</button></div></header>`;}
function focusStrip(){return `<div class="focus-strip"><span class="mission-label"><i></i> MISSION ${p().mission.number} · YOUR CHOSEN TABLES</span><div class="focus-chips">${p().tables.map(t=>`<span>${t}<small>×</small></span>`).join('')}</div><button class="text-button" id="choose-tables">Change tables</button><span class="star-balance">✦ ${p().coins}<small>star sparks</small></span></div>`;}
function tableChooser(){return `<section class="table-chooser"><div><h2>Which tables are we exploring?</h2><p>Choose one or a few. Every question will come from these tables.</p></div><div class="table-buttons">${Array.from({length:12},(_,i)=>i+1).map(t=>`<button data-table="${t}" aria-pressed="${p().tables.includes(t)}" class="${p().tables.includes(t)?'selected':''}">${t}<small>times</small></button>`).join('')}</div><button class="small-button" id="close-tables">Ready to play ✓</button></section>`;}
function home(){const pr=p(),table=pr.activeRocket,s=rocketStatus(pr,table),level=badgeCount(pr),next=BADGES[level];return `${focusStrip()}${tablePicker?tableChooser():''}<section class="page-intro space-intro"><div><span class="eyebrow">MISSION CONTROL · HELP THE MULTIPLOIDS GET HOME</span><h1>A little crew. A long way home.</h1><p>Our rockets need your number skills. Choose a rocket and get it ready for lift-off.</p></div><div class="mission-copilot"><div class="copilot-model">${creature(pr)}</div><div><small>YOUR MULTIPLOID</small><strong>${pr.species==='blob'?'A little beginning':esc(pr.palName)}</strong><button class="secondary" id="make-creature">${pr.species==='blob'?'Meet your Multiploid ✧':'Make it more you ✧'}</button></div></div></section><div class="reward-paths"><div class="character-path"><span>✧ PRACTICE BUILDS YOUR CHARACTER</span><strong>${level} / 6 creation badges</strong><small>${next?Math.max(0,next.at-pr.mission.answers.length)+' different questions to your next choice':'Every creation badge earned!'}</small></div><div class="rocket-path"><span>↟ CORRECT MODULES PREPARE YOUR ROCKET</span><strong>Rocket ${table} · ${s.done} / 5 systems ready</strong><small>Each finished activity prepares one part for launch.</small></div></div><section class="fleet-section"><div class="fleet-heading"><div><span class="eyebrow">YOUR TIMES-TABLE ROCKETS</span><p>${pr.tables.length} selected · ${fleetExpanded?'all rockets shown':'your active rocket stays in view'}</p></div>${pr.tables.length>3?`<button class="secondary" id="toggle-fleet" aria-expanded="${fleetExpanded}" aria-controls="fleet-bay">${fleetExpanded?'Show fewer rockets ↑':'Show all '+pr.tables.length+' rockets ↓'}</button>`:''}</div><div id="fleet-bay" class="fleet-bay ${fleetExpanded?'expanded':'collapsed'}" aria-label="Your chosen times-table rockets">${fleetPreview(pr.tables,table,fleetExpanded).map(t=>{const r=rocketStatus(pr,t);return `<button class="fleet-card ${t===table?'active':''} ${r.launched?'launched':''}" data-rocket="${t}" aria-pressed="${t===table}"><div class="fleet-rocket">${rocketArt(t,{percent:r.percent,launched:r.launched,small:true})}</div><div><small>THE ${t} TIMES TABLE</small><h2>Rocket ${t}</h2><span>${r.launchedToday?'Home safe today ✓':r.launched?'Ready for another flight':r.ready?'Final launch check ready':r.done+' / 5 systems ready'}</span><div class="fleet-meter fleet-strips" aria-label="${r.done} of 5 systems complete">${Object.entries(SYSTEMS).map(([mode,system])=>`<span class="fleet-strip ${r.systems[mode].complete?'complete':''}" title="${system.part}: ${r.systems[mode].count}/${r.systems[mode].total}" aria-label="${system.part}: ${r.systems[mode].count} of ${r.systems[mode].total}"><i style="width:${r.systems[mode].count/r.systems[mode].total*100}%"></i></span>`).join('')}</div></div><b>${r.launched?'✓':t===table?'●':'→'}</b></button>`;}).join('')}</div></section><div class="rocket-mission-layout"><section class="mission-systems"><div class="section-heading"><div><span class="eyebrow">ROCKET ${table} · ONLY THE ${table} TIMES TABLE</span><h2>Let’s get this ship ready.</h2></div><span>Missed facts stay ready for another go.</span></div>${pr.rockets[table]?.launchReview?`<div class="launch-recap-banner"><strong>Just the facts for your next flight.</strong><p>These recap buttons focus on the missed fact and those not reached. Facts already right in the launch check stay out of recap.</p></div>`:''}<div class="systems-grid">${Object.entries(SYSTEMS).map(([mode,system])=>{const status=s.systems[mode],access=moduleAccess(pr,table,mode);return `<button class="system-card system-${mode} ${status.complete?'system-complete':''}" data-start="${mode}" ${!access.facts.length?'disabled':''} style="--system:${system.colour}"><span class="system-icon">${status.complete?'✓':system.icon}</span><div><small>${system.part.toUpperCase()}</small><h3>${system.title}</h3><p>${system.description}</p></div><div class="system-progress"><span>${status.count} / ${status.total} correct</span><strong>${!status.complete?'Have a go →':access.facts.length?access.kind==='targeted'?'Recap '+access.facts.length+' launch facts →':'Optional recap →':access.kind==='targeted'?'Launch recap done ✓':'Ready for launch ✓'}</strong><i><b style="width:${status.count/status.total*100}%"></b></i></div></button>`;}).join('')}</div></section><aside class="rocket-readiness ${s.launched?'home-safe':''}"><div class="rocket-display ${s.ready?'ready':''} ${s.launched?'launched':''}">${starsArt()}${rocketArt(table,{percent:s.percent,launched:s.launched})}</div><h2>${s.launchedToday?'Home safe today!':'Rocket '+table}</h2><p>${s.launchedToday?'Lovely teamwork. Recap any module now and take a new launch check tomorrow.':s.ready?'Systems ready! Get all twelve facts right in a row to launch.':'Every green system brings our little crew closer to home.'}</p><div class="readiness-percent"><strong>${s.percent}%</strong><span>launch readiness</span></div><ul class="ship-checklist">${Object.entries(SYSTEMS).map(([m,sys])=>`<li class="${s.systems[m].complete?'ready':''}"><span>${s.systems[m].complete?'✓':'○'}</span>${sys.part}<small>${s.systems[m].count}/${s.systems[m].total}</small></li>`).join('')}</ul><button class="primary launch-button" id="launch-rocket" ${!s.ready||s.launchedToday?'disabled':''}>${s.launchedToday?'Launched today ✓':s.ready?hasLaunchProof(pr,table)?'Continue lift-off ↟':s.launched?'Launch again · final check ↟':'Final launch check ↟':'Prepare all 5 systems to launch'}</button>${s.launchedToday?'<button class="text-button" id="replay-launch">Watch today’s lift-off again ↟</button>':''}<div class="crew-note"><span>${esc(pr.palName)} ${pr.species==='blob'?'is waiting to meet you':'is counting on you'}.</span><button class="text-button" data-go="workshop">Make your Multiploid yours →</button></div></aside></div><section class="mixed-missions"><div class="section-heading"><div><span class="eyebrow">THE WHOLE FLEET · ALL YOUR SELECTED TABLES</span><h2>A little further into space?</h2></div></div><div class="mixed-grid"><button class="cosmo-card" data-start="skyhop"><div class="cosmo-card-art">${planetArt('planet','#c5a8ec')}</div><div><small>THE MIXED-TABLE STREAK CHALLENGE</small><h2>Cosmo Hop</h2><p>Planets, friendly aliens and curious black holes. One right answer, one new stop.</p><span>⚑ Best on your ${esc(focusLabel(pr.tables))}: <b>${pr.records[focusKey(pr.tables)]||0}</b></span><strong>${resumeCosmo(pr)?'Continue · streak '+resumeCosmo(pr).streak+' ↗':'Start · current streak 0 ↗'}</strong></div></button><button class="flight-check-card" data-start="test"><span class="big-glyph">⌁</span><small>TEST YOURSELF · ALL YOUR SELECTED TABLES</small><h2>Fleet Flight Check</h2><p>Every fact from your chosen tables, once each. No hints or countdown. See your results at the end.</p><span>${factsFor(pr.tables).length} questions · take your time</span><strong>Try the whole fleet →</strong></button></div></section><section class="starbase-invite"><div class="starbase-sign">✦</div><div><small>OFF-DUTY ADVENTURES</small><h2>The Starbase</h2><p>Two free games to start. Each different rocket home unlocks another game. ${availableGames(pr).length} games ready.</p></div><button class="secondary" data-go="starbase">Enter the Starbase →</button></section>`;}

function openSetup(mode=null){draft={name:'',species:'orbit',voice:'heart2'};modal={type:'setup',mode};render();}
function fact(){return session.mode==='skyhop'?session.run.deck[session.run.index]:session.deck[session.index];}
function begin(mode){if(!MODES[mode])return;if(!p().mission.locks.identity){openSetup(mode);return;}stopReading();ensureFleet(p());const table=p().activeRocket;if(mode==='launchcheck'&&!rocketStatus(p(),table).ready){toast('Prepare all five systems first.');return;}let launchCheck=null;if(mode==='launchcheck'){try{launchCheck=createLaunchCheck(p(),table);}catch(error){toast(error.message);return;}}const deck=mode==='launchcheck'?launchCheck.items:mode==='skyhop'||mode==='test'?deckFor(p().tables):rocketDeck(p(),table,mode);if(!deck.length){toast('This system is ready. Return to your ship for the final launch check.');view='home';render();return;}session={recap:SYSTEMS[mode]?moduleAccess(p(),table,mode).kind:null,mode,table,deck,index:0,answer:'',mistakes:0,correct:0,seen:0,feedback:'',busy:false,assisted:false,shownGroups:1,rows:0,marks:[],paths:[],drawTool:'star',run:mode==='skyhop'?(resumeCosmo(p())||createRun(p())):null,launchCheck,check:mode==='test'?{tables:[...p().tables],items:deck,answers:[]}:null};if(session.run&&!session.run.route)session.run.route=Array.from({length:6},(_,i)=>i).sort(()=>Math.random()-.5);view='game';render();sayFact(fact(),mode,p().voiceStyle);}

function creatureForStage(){const pr=p();return `<div class="game-creature" id="hop-creature">${creature(pr)}</div>`;}
function groups(f){return `<div class="cargo-groups">${Array.from({length:f.a},(_,i)=>`<button class="cargo-crate ${i<session.shownGroups?'loaded':''}" data-crate="${i}" aria-label="Crate ${i+1}, ${f.b} moonberries"><div>${Array.from({length:f.b},()=>'<i></i>').join('')}</div><span>${i<session.shownGroups?f.b:'Tap to load'}</span></button>`).join('')}</div><p class="visual-caption">${session.shownGroups} of ${f.a} crates loaded · ${f.b} in each crate</p>`;}
function gameScene(){const f=fact(),mode=session.mode;if(mode==='launchcheck')return `<div class="learning-stage launch-check-stage ignition-${Math.floor(session.launchCheck.streak/3)} ${session.launchCheck.complete?'launch-lights-top':''}" style="--charge:${session.launchCheck.streak/12}">${starsArt()}<div class="stage-heading"><span>ROCKET ${session.table} · FINAL LAUNCH CHECK</span><h2>Twelve facts. One brilliant run.</h2><p>Just the ${session.table} times table, in a fresh random order. All twelve right in a row!</p></div><div class="preflight-rocket">${rocketArt(session.table,{percent:100})}<div class="preflight-smoke" aria-hidden="true">${Array.from({length:6},(_,i)=>`<i style="--puff:${i}"></i>`).join('')}</div></div><div class="launch-lamps">${LAUNCH_COLOURS.map((colour,i)=>`<i style="--lamp:${colour};--step:${i}" class="${i<session.launchCheck.streak?'lit':''}" aria-label="Launch lamp ${i+1}${i<session.launchCheck.streak?', lit':', off'}">${i+1}</i>`).join('')}</div><div class="launch-streak"><strong>${session.launchCheck.streak}</strong><span>of 12 launch lights</span></div><div class="small-game-pal">${creature(p())}</div></div>`;if(mode==='skyhop'){const stop=encounterAt(session.run);return `<div class="skyhop-stage cosmic-stage encounter-${stop.type}">${starsArt()}<div class="encounter-art">${planetArt(stop.type,stop.colour)}</div><div class="encounter-label"><small>NEXT STOP IN OUR SPACE STORY</small><h2>${stop.name}</h2><p>${stop.message}</p></div><div class="altitude-tag"><span>YOUR SPACE HOPS</span><strong>${session.run.streak}<small>in a row</small></strong></div><span class="target-cloud">${Math.floor(session.run.streak/5+1)*5}<small>next milestone</small></span>${creatureForStage()}<div class="next-hop-platform"><span>✦</span></div><div class="landing-platform"><span></span><b>✦</b></div><div class="record-flag">⚑ Best ${p().records[session.run.key]||0}</div><div class="climb-trail">${Array.from({length:5},(_,i)=>`<i class="${i<session.run.streak%5?'lit':''}">✦</i>`).join('')}</div></div>`;}
if(mode==='test')return `<div class="learning-stage flight-check-stage">${starsArt()}<div class="stage-heading"><span>FLEET FLIGHT CHECK</span><h2>Your whole crew is cheering.</h2><p>Only your ${esc(focusLabel(p().tables))}. One calm question at a time.</p></div><div class="check-fleet">${p().tables.slice(0,5).map(t=>rocketArt(t,{small:true})).join('')}</div><div class="small-game-pal">${creature(p())}</div><span class="check-count">${session.index+1} / ${session.deck.length}</span></div>`;
if(mode==='arrays')return `<div class="learning-stage array-stage">${starsArt()}<div class="stage-heading"><span>ROCKET ${session.table} · ARRAY SHIELDS</span><h2>Build ${f.b} rows of ${f.a} stars.</h2><p>Drag a star row into the shield. You can tap it too.</p></div><div class="hands-on-copilot">${creature(p())}</div><div class="array-builder"><button id="star-row-source" class="star-row-source" aria-label="Add one row of ${f.a} stars" ${session.busy?'disabled':''}><span>${Array.from({length:f.a},()=>'<i>✦</i>').join('')}</span><small>Drag or tap · one row of ${f.a}</small></button><div id="array-target" class="array-target" aria-label="Your shield array"><div class="array-count">${session.rows} rows × ${f.a} stars</div>${Array.from({length:session.rows},(_,i)=>`<div class="array-row"><span>${Array.from({length:f.a},()=>'<i>✦</i>').join('')}</span><button data-remove-row="${i}" aria-label="Return row ${i+1}">↩</button></div>`).join('')||'<p>Drop your rows here.<br>Equal rows make an array.</p>'}</div><button class="text-button" id="clear-rows">Return all rows ↩</button></div></div>`;
if(mode==='draw')return `<div class="learning-stage draw-stage"><div class="stage-heading"><span>ROCKET ${session.table} · ORBIT SKETCH</span><h2>${f.b} orbits. ${f.a} stars in each.</h2><p>Place your star groups, then tell me the total.</p></div><div class="hands-on-copilot">${creature(p())}</div><div class="orbit-tools">${[['star','✦ Star stamp'],['pen','✎ Space pen'],['eraser','⌫ Rubber']].map(([tool,label])=>`<button class="small-button ${session.drawTool===tool?'selected':''}" data-draw-tool="${tool}">${label}</button>`).join('')}<button class="text-button" id="clear-orbits">Clear</button></div><p class="orbit-tool-note">Stamp stars to count them. The pen is for your extra space pictures.</p><canvas id="orbit-canvas" width="720" height="430" aria-label="Place ${f.a} stars in each of ${f.b} orbits. Draw with the pen for decoration."></canvas><div class="orbit-accessible">${Array.from({length:f.b},(_,i)=>`<div><button class="small-button" data-orbit-add="${i}">+ Star in orbit ${i+1}</button><button class="small-button" data-orbit-remove="${i}" aria-label="Remove a star from orbit ${i+1}">−</button></div>`).join('')}</div><p id="draw-counts" class="draw-counts">${Array.from({length:f.b},(_,i)=>'Orbit '+(i+1)+': '+session.marks.filter(m=>m.group===i).length+'/'+f.a).join(' · ')}</p></div>`;
if(mode==='cargo')return `<div class="learning-stage cargo-stage">${starsArt()}<div class="stage-heading"><span>ROCKET ${session.table} · MOONBERRY DELIVERY</span><h2>${f.a} crates. ${f.b} in each.</h2></div>${groups(f)}<div class="small-game-pal">${creature(p())}</div><div class="stage-ground"></div></div>`;
if(mode==='bridge')return `<div class="learning-stage bridge-stage">${starsArt()}<div class="stage-heading"><span>ROCKET ${session.table} · THE LAUNCH GANTRY</span><h2>Find the missing bridge section.</h2></div><div class="gantry-rocket">${rocketArt(session.table,{small:true})}</div><div class="bridge-river"></div><div class="bridge-bank bank-left"></div><div class="bridge-bank bank-right"></div><div class="bridge-stones"><span>${f.a}</span><span>×</span><span class="missing-stone">?</span><span>=</span><span>${f.total}</span></div><div class="small-game-pal">${creature(p())}</div></div>`;
const fuel=rocketStatus(p(),session.table).systems.power;return `<div class="learning-stage power-stage">${starsArt()}<div class="stage-heading"><span>ROCKET ${session.table} · FUEL STATION</span><h2>Every correct fact adds a fuel cell.</h2><p>All twelve: ${session.table} × 1 through ${session.table} × 12.</p></div><div class="power-machine"><div class="machine-aerial"></div><div class="machine-window">${Array.from({length:12},(_,i)=>`<i class="${fuel.passed.includes(session.table+'x'+(i+1))?'charged':''}" title="${session.table} × ${i+1}">${i+1}</i>`).join('')}</div><span class="machine-dial">ϟ</span><span class="machine-label">CELLS ${fuel.count} / 12</span><div class="machine-feet"></div></div><div class="small-game-pal">${creature(p())}</div></div>`;}

function game(){if(session.finished)return finish();const f=fact(),mode=session.mode,sky=mode==='skyhop',next=BADGES[badgeCount(p())];return `<div class="game-top"><button class="text-button" id="leave-game">← Back to Mission Control</button><span>${icon(mode)} ${MODES[mode].name}</span><span>${sky?'Best on these tables: '+(p().records[session.run.key]||0):mode==='test'?(session.index+1)+' / '+session.deck.length+' facts':mode==='launchcheck'?session.launchCheck.streak+' / 12 in a row':'Rocket '+session.table+' · '+(session.index+1)+' / '+session.deck.length}</span></div><div class="game-layout"><section class="game-stage">${gameScene()}</section><section class="question-card"><div class="question-speaker"><span class="speaker-dot"></span><strong>${esc(p().palName)} asks…</strong><button class="icon-button" id="hear-question" aria-label="Hear the question">♫</button></div><h1>${mode==='bridge'?'Which number is missing?':mode==='cargo'?'How many altogether?':mode==='arrays'?'How many stars in your array?':mode==='draw'?'How many stars altogether?':'What’s the answer?'}</h1><p class="question-caption">${sky?'Take your time. Every answer is a new step.':MODES[mode].description}</p><div class="equation" aria-label="${f.a} times ${mode==='bridge'?'what number equals '+f.total:f.b}"><span>${f.a}</span><b>×</b><span class="${mode==='bridge'?'unknown':''}">${mode==='bridge'?'?':f.b}</span>${mode==='bridge'?'<b>=</b><span>'+f.total+'</span>':''}</div><div class="answer-wrap"><label for="answer">${mode==='bridge'?'The missing multiplier':'My answer'}</label><input id="answer" readonly inputmode="none" autocomplete="off" aria-describedby="answer-feedback" value="${session.answer}" placeholder="?" ${session.busy?'disabled':''}></div><div class="number-pad">${[1,2,3,4,5,6,7,8,9,'clear',0,'back'].map(n=>`<button data-digit="${n}" ${session.busy?'disabled':''} aria-label="${n==='back'?'Delete last digit':n==='clear'?'Clear answer':n}">${n==='clear'?'Clear':n==='back'?'⌫':n}</button>`).join('')}</div><button class="primary answer-button" id="check-answer" ${session.busy?'disabled':''}>${sky?'Hop · streak '+session.run.streak+' ↟':mode==='test'?'Save & next →':mode==='launchcheck'?'Light the next launch lamp ↟':'Let’s check →'}</button><p class="answer-feedback ${session.busy?'busy':''}" id="answer-feedback" role="status">${esc(session.feedback||(sky?'One mistake ends the run. Your progress stays yours.':mode==='test'?'No hints. Your results are waiting at the end.':mode==='launchcheck'?'All twelve, right in a row. Your prepared systems stay safe.':'Trying earns badges. Correct answers prepare this rocket.'))}</p><p data-audio-note class="audio-note"></p>${mode==='test'?'<button class="text-button" id="skip-test">Skip this fact for now →</button>':''}${!sky&&mode!=='test'&&mode!=='launchcheck'?'<div class="question-tools"><button class="text-button" id="hint">Show me how</button><button class="text-button" id="skip">Skip for now →</button></div>':''}<div class="next-badge"><span>✧ ${badgeCount(p())} badges</span><small>${next?Math.max(0,next.at-p().mission.answers.length)+' different questions to your next badge':'Rainbow suit unlocked! Find it in Your Multiploid → My collection.'}</small><button class="text-button" data-go="workshop">Your Multiploid →</button></div></section></div><div class="module-exit"><button class="secondary mission-control-button" data-go="home">⌂ Back to Mission Control</button></div>`;}
function digit(value){if(view!=='game'||!session||session.busy||session.finished||modal)return;unlockVoice();if(value==='back')session.answer=session.answer.slice(0,-1);else if(value==='clear')session.answer='';else if(session.answer.length<3)session.answer=(session.answer==='0'?'':session.answer)+value;const input=$('#answer');if(input)input.value=session.answer;}
function submit(){
 if(!session||session.busy||session.finished||modal)return;
 if(session.mode==='cargo'&&session.shownGroups<fact().a){session.feedback='Load all '+fact().a+' crates first. Each one has the same number inside.';render();return;}
 if(!session.answer){session.feedback='Tap a number to have a go.';$('#answer-feedback').textContent=session.feedback;return;}
 if(session.mode==='test'){submitCheck(session.answer);return;}if(session.mode==='launchcheck'){submitLaunchCheck(session.answer);return;}
 const f=fact(),mode=session.mode,before=badgeCount(p()),construction=validConstruction(session,f),correct=construction&&Number(session.answer)===(mode==='bridge'?f.b:f.total);
 if(mode==='skyhop'){const result=scoreHop(p(),session.run,session.answer),praise=result.correct?nextCosmoPraise(session.run):null;bookmarkCosmo(p(),session.run);save();session.busy=true;session.feedback=correct?result.milestone?session.run.streak+' space hops! Five star sparks for your pocket.':session.run.streak>session.run.baseline?'A new personal best. Keep exploring!':praise.text:f.a+' × '+f.b+' = '+f.total+'. Let’s take a new flight soon.';render();if(correct){if(state.sound){soundEffect(result.milestone?'celebrate':'travel');say([result.milestone?session.run.streak%10===0?'ten':'five':session.run.streak===session.run.baseline+1&&session.run.baseline?'record':praise.key],p().voiceStyle);}$('#hop-creature')?.classList.add('jumping');$('.skyhop-stage')?.classList.add('hopping');}else $('#hop-creature')?.classList.add('caught');armAdvance(correct?1000:1700,()=>{if(correct){nextRunFact(session.run);session.answer='';session.busy=false;session.feedback='';render();sayFact(fact(),mode,p().voiceStyle);}else{session.finished=true;render();}});}
 else{const outcome=answerOutcome(session.mistakes,correct);recordPractice(p(),f,mode,{correct,assisted:session.assisted});recordRocket(p(),session.table,mode,f,{correct,assisted:session.assisted});save();if(correct){session.correct++;session.busy=true;session.feedback='You’ve got it! '+f.a+' × '+f.b+' = '+f.total+(session.assisted?'. Good learning with some help.':session.recap==='prepare'?'. Another check saved for Rocket '+session.table+'.':'. Launch recap remembered!');if(state.sound){soundEffect('celebrate');say(['brilliant'],p().voiceStyle);}}else if(outcome==='retry'){session.mistakes++;session.answer='';if(mode==='arrays'&&!construction)session.rows=0;session.feedback=!construction?mode==='draw'?'Check the stars in each orbit. Make each group equal, then try once more.':'Let’s rebuild the array. Drag the equal rows back and have one more go.':'A brave try! Listen again and have one more go.';if(state.sound)say(['retry'],p().voiceStyle);}else{session.busy=true;session.feedback='Let’s keep exploring. '+f.a+' × '+f.b+' = '+f.total+'. This fact stays ready for later.';}render();if(session.busy)armAdvance(1400,advancePractice);}
 if(badgeCount(p())>before)toast('✧ Badge '+badgeCount(p())+'! '+BADGES[badgeCount(p())-1].reward+' unlocked.');
}

function armAdvance(ms,fn){clearTimeout(advanceTimer);const current=session,who=p().id;advanceTimer=setTimeout(()=>{if(view==='game'&&session===current&&p().id===who&&!modal)fn();},ms);}
function advancePractice(){session.index++;session.seen++;session.mistakes=0;session.assisted=false;session.shownGroups=1;session.rows=0;session.marks=[];session.paths=[];session.busy=false;session.answer='';session.feedback='';if(session.index>=session.deck.length)session.finished=true;render();if(!session.finished)sayFact(fact(),session.mode,p().voiceStyle);}
function finish(){if(session.mode==='launchcheck')return `<section class="finish-page"><span class="eyebrow">ROCKET ${session.table} · LAUNCH CHECK</span><h1>A fresh run is waiting.</h1><div class="finish-score">${session.launchCheck.streak}<span>of 12 right in a row</span></div><p>${session.failedFact.a} × ${session.failedFact.b} = ${session.failedFact.total}. Our crew is safe. All five prepared systems stay ready.</p><p>Recap only the missed fact and those we hadn’t reached. The next launch check shuffles all twelve again.</p><div class="finish-creature">${creature(p())}</div><div class="button-row"><button class="primary" data-go="home">Back to ship · targeted recap →</button><button class="secondary" data-start="launchcheck">Try a fresh launch check ↟</button></div></section>`;if(session.mode==='test'){const r=session.checkResult;return `<section class="finish-page"><span class="eyebrow">FLEET FLIGHT CHECK · YOUR SELECTED TABLES</span><h1>Look what you’re learning.</h1><div class="finish-score">${r.score}<span>of ${r.total} correct</span></div><p>No lost badges. These are the facts ready for another little go.</p><div class="check-results">${r.results.map(f=>`<div class="${f.correct?'correct':''}"><strong>${f.a} × ${f.b} = ${f.total}</strong><span>${f.correct?'✓ Remembered':f.answer==='—'?'Skipped':'You wrote '+esc(f.answer)}</span></div>`).join('')}</div><div class="button-row"><button class="primary" data-start="test">Another flight check →</button><button class="secondary" data-go="home">Back to Mission Control</button></div></section>`;}
const sky=session.mode==='skyhop',run=session.run,score=sky?run.streak:session.correct,s=sky?null:rocketStatus(p(),session.table).systems[session.mode];return `<section class="finish-page"><span class="eyebrow">${sky?'A FRIENDLY SHUTTLE CAUGHT YOU':'ROCKET '+session.table+' · '+SYSTEMS[session.mode].title.toUpperCase()}</span><h1>${sky?run.newBest?'A new personal best!':score?'What a little space adventure.':'Every journey has a first hop.':s.complete?SYSTEMS[session.mode].part+'!':'A little closer to lift-off.'}</h1><div class="finish-score">${sky?score:s.count}<span>${sky?'space hops in a row':'of '+s.total+' system checks complete'}</span></div><p>${sky?'Planets, new friends and a record that stays yours.':s.complete?'That part of Rocket '+session.table+' is ready. Your correct checks stay saved.':'Skipped, shown and twice-missed facts stay here for another go. Your completed checks are saved.'}</p>${sky?`<div class="result-pills"><span>⚑ Best ${p().records[run.key]||0}</span><span>✦ ${run.milestones.length*5} milestone sparks</span><span>${esc(focusLabel(run.tables))}</span></div>`:`<div class="result-pills"><span>↟ Rocket ${session.table}: ${rocketStatus(p(),session.table).done} / 5 systems ready</span><span>✧ ${badgeCount(p())} creation badges</span></div>`}<div class="finish-creature">${creature(p())}</div><div class="button-row"><button class="primary" data-go="home">${sky?'Back to Mission Control':'Back to ship · Rocket '+session.table+' →'}</button>${sky||moduleAccess(p(),session.table,session.mode).facts.length?`<button class="secondary" data-start="${session.mode}">${sky?'One more space hop? ↟':!s.complete?'Try remaining facts →':session.recap==='targeted'?'Continue targeted recap →':'Optional extra practice →'}</button>`:''}<button class="text-button" data-go="workshop">Your Multiploid ✧</button></div></section>`;}

function rainbowSuitCard(pr){return `<article class="choice-card rainbow-suit"><span class="eyebrow">BADGE 6 · RAINBOW EXPLORER</span><h2>Your rainbow suit!</h2><p>Seven bright colours, yours to keep. Wear it with your current Multiploid.</p><div class="rainbow-ribbon" aria-hidden="true"></div><button class="${pr.wearing.coat==='coat-rainbow'?'secondary':'primary'}" data-equip="coat-rainbow" data-category="coat">${pr.wearing.coat==='coat-rainbow'?'Wearing my rainbow ✓':'Wear my rainbow suit 🌈'}</button></article>`;}
function weeklySuitCard(r){return `<article class="choice-card weekly-suit"><span class="eyebrow">THIS WEEK’S SPACE SUIT</span><h2>${esc(r.suit.label.split(' · ')[0])}</h2><div class="suit-swatch" style="--suit-colour:${r.suit.colour};--suit-accent:${r.suit.accent}" aria-hidden="true">✦</div><p>Practise 20 different questions this week to earn it. A new design arrives every Monday. Earned suits stay yours.</p><progress max="20" value="${r.count}" aria-label="Weekly suit progress"></progress><p>${r.owned?'In your outfit collection ✓':r.count+' / 20 questions'}</p>${r.owned?'<button class="secondary" data-equip="'+r.suit.id+'" data-category="coat">Wear this week’s suit</button>':r.ready&&p().species!=='blob'?'<button class="primary" id="claim-weekly-suit">My new suit! Wear it ✦</button>':'<small>Extra practice of completed questions does not add reward progress.</small>'}</article>`;}
function colourChoices(){return ['mint','lilac','peach','blue','rose','aqua','lemon',...(p().rainbowUnlocked?['rainbow']:[])].map(c=>`<button class="swatch ${draft.colour===c?'selected':''}" style="--swatch:${c==='rainbow'?'linear-gradient(135deg,#ff244b,#ff861c,#ffda16,#19c857,#04bcea,#4054f4,#b425ed)':COLOURS[c]}" data-preview-colour="${c}" aria-label="${c}"></button>`).join('');}
function workshop(){const pr=p(),n=badgeCount(pr),weekly=weeklyReward(pr),preview={...pr,...(draft.colour?{colour:draft.colour}:{}),...(draft.antennae?{antennae:draft.antennae}:{})};return `${focusStrip()}<section class="page-intro"><div><span class="eyebrow">A LITTLE MORE YOU, EVERY TIME</span><h1>${pr.species==='blob'?'Your little beginning.':esc(pr.palName)+'’s workshop.'}</h1><p>Try before choosing. Body colour and antennae stay for this mission.</p></div>${session?.paused?'<button class="primary" id="resume-round">Back to my round →</button>':'<button class="secondary" data-go="home">Back to Mission Control →</button>'}</section><div class="workshop-grid"><aside class="workshop-preview">${creature(preview)}<h2>${esc(pr.palName)}</h2><p>Tap to say hello. Double-tap to tickle.<br>Hold for a happy purr.</p><button class="small-button" id="dance">A little dance ♫</button></aside><section class="workshop-choices">${pr.mission.locks.identity?weeklySuitCard(weekly):''}${pr.rainbowUnlocked?rainbowSuitCard(pr):''}${!pr.mission.locks.identity?'<article class="choice-card"><span class="eyebrow">BADGE 1 · READY TO LEARN</span><h2>Let’s meet your Multiploid.</h2><p>Choose a name, a shape and a clear voice. Just for deciding to have a go.</p><button class="primary" id="make-creature">Create my Multiploid →</button></article>':''}${n>=2&&!pr.mission.locks.colour?`<article class="choice-card"><span class="eyebrow">BADGE 2 · A SPLASH OF YOU</span><h2>Pick your colour.</h2><div class="swatches">${colourChoices()}</div>${draft.colour?'<button class="primary" id="confirm-colour">Keep this colour for my mission ✓</button>':''}</article>`:''}${n>=3&&!pr.mission.locks.antennae?`<article class="choice-card"><span class="eyebrow">BADGE 3 · HELLO UP THERE</span><h2>A little something on top.</h2><div class="shape-options">${['none','radar','satellite','bolts'].map(a=>`<button class="${draft.antennae===a?'selected':''}" data-preview-antennae="${a}">${a==='none'?'Smooth & simple':a[0].toUpperCase()+a.slice(1)}</button>`).join('')}</div>${draft.antennae?'<button class="primary" id="confirm-antennae">Keep these antennae ✓</button>':''}</article>`:''}${Object.entries(ITEMS).filter(([cat])=>n>=(['hat','coat'].includes(cat)?4:5)&&!pr.mission.claimed[cat]).map(([cat,items])=>`<article class="choice-card"><span class="eyebrow">BADGE ${['hat','coat'].includes(cat)?4:5} · ${cat.toUpperCase()}</span><h2>Choose a little ${cat==='coat'?'jacket':cat}.</h2><div class="item-choices">${items.filter(i=>i.id!=='coat-rainbow'&&!SHOP.some(s=>s.id===i.id)).map(i=>`<button data-claim="${i.id}" data-category="${cat}"><i style="background:${i.colour}">${cat==='hat'?'△':cat==='coat'?'♢':cat==='shoes'?'⌁':'◎'}</i>${i.label}<small>Choose & wear</small></button>`).join('')}</div></article>`).join('')}${pr.mission.locks.identity&&!([n>=2&&!pr.mission.locks.colour,n>=3&&!pr.mission.locks.antennae,n>=4&&(!pr.mission.claimed.hat||!pr.mission.claimed.coat),n>=5&&(!pr.mission.claimed.shoes||!pr.mission.claimed.glasses)].some(Boolean))?'<article class="choice-card quiet-card"><span>✧</span><h2>There’s more in you.</h2><p>Keep playing to discover your next creation badge. Your chosen features are already on your Multiploid.</p><button class="primary" data-go="home">Let’s practise →</button></article>':''}<details class="collection"><summary>My collection · eyes & outfits</summary><div class="swatches">${Object.entries(EYE_COLOURS).map(([c,v])=>`<button class="swatch ${pr.eyeColour===c?'selected':''}" data-eye="${c}" aria-label="${c} eyes" style="--swatch:${v}"></button>`).join('')}</div>${Object.entries(wardrobeItems(pr)).filter(([,items])=>items.some(i=>pr.owned.includes(i.id))).map(([cat,items])=>`<h3>${cat}</h3><div class="button-row"><button class="small-button" data-equip="none" data-category="${cat}">Take off</button>${items.filter(i=>pr.owned.includes(i.id)).map(i=>`<button class="small-button ${pr.wearing[cat]===i.id?'selected':''}" data-equip="${i.id}" data-category="${cat}">${i.label}</button>`).join('')}</div>`).join('')}</details><details class="collection"><summary>The spark shop · ${pr.coins} ✦</summary><p>A few little extras for your hard-earned sparks.</p><div class="item-choices">${SHOP.map(s=>{const i=ITEMS[s.category].find(i=>i.id===s.id);return `<button data-buy="${i.id}" ${pr.owned.includes(i.id)||pr.coins<s.cost?'disabled':''}><i style="background:${i.colour}">✧</i>${i.label}<small>${pr.owned.includes(i.id)?'Already yours':s.cost+' ✦'}</small></button>`;}).join('')}</div></details></section></div>`;}
function progress(){const pr=p(),n=badgeCount(pr);return `${focusStrip()}<section class="page-intro"><div><span class="eyebrow">LOOK WHAT YOU’RE LEARNING</span><h1>Your flight log.</h1><p>Read your tables aloud, follow your facts and check your fleet. Three learning lights show what you’ve practised; the five rocket systems track launch readiness.</p></div></section><section class="badges-grid">${BADGES.map((b,i)=>`<article class="badge-card ${n>i?'earned':''}"><span>✧<b>${i+1}</b></span><h3>${n>i?b.title:'A surprise to discover'}</h3><p>${n>i?b.reward:(b.at||'Start')+' different questions'}</p></article>`).join('')}</section><div class="facts-legend"><span>▦ See it</span><span>⋯ Solve it</span><span>ϟ Recall it</span><strong>${greenCount(pr)} / ${factsFor(pr.tables).length} facts glowing</strong></div><div class="table-progress">${pr.tables.map(a=>`<section class="table-progress-card"><div class="table-audio-heading"><h2>The ${a} times table</h2><button class="small-button" data-read-table="${a}" aria-pressed="false">♫ Read this table</button></div><p class="table-rocket-status">Rocket ${a} · ${rocketStatus(pr,a).done}/5 systems ready${rocketStatus(pr,a).launched?' · Home safe ✓':''}</p>${factsFor([a]).map(f=>`<div data-read-fact="${a}:${f.b}" class="fact-row ${lights(pr,f.id).length===3?'green':''}"><strong>${f.a} × ${f.b} = ${f.total}</strong><span>${['see','solve','recall'].map((l,i)=>`<i class="${lights(pr,f.id).includes(l)?'lit':''}" aria-label="${l} ${lights(pr,f.id).includes(l)?'complete':'ready to try'}">${['▦','⋯','ϟ'][i]}</i>`).join('')}</span></div>`).join('')}</section>`).join('')}</div><section class="records-panel"><h2>Your Cosmo Hop records</h2>${Object.entries(pr.records).length?Object.entries(pr.records).map(([key,best])=>`<div><span>⚑ ${esc(focusLabel(key.split('-').map(Number)))}</span><strong>${best} in a row</strong></div>`).join(''):'<p>Your first run is the beginning of your record book.</p>'}</section>${pr.history.length?`<section class="records-panel"><h2>Our little mission album</h2><div class="album-grid">${pr.history.map(h=>`<article><i style="background:${COLOURS[h.colour]||COLOURS.grey}">✧</i><h3>${esc(h.name)}</h3><p>Mission ${h.number} · ${h.questions} different questions</p></article>`).join('')}</div></section>`:''}`;}
function grownups(){return `<section class="page-intro"><div><span class="eyebrow">MISSION SUPPORT · GROWN-UPS</span><h1>Your explorer’s space.</h1><p>Multiplication only. Free local speech and learning content.</p></div></section><div class="grownup-grid"><section class="choice-card"><h2>Explorer name</h2><label for="explorer-name">The name shown in the profile picker</label><input id="explorer-name" value="${esc(p().name)}" maxlength="20"><button class="primary" id="save-name">Save name</button><h3>One table, one rocket</h3><p>Each selected table has a numbered rocket. Rocket Fuel checks ×1–×12. Cargo and Launch Bridge also cover all twelve facts. Array Shields has four construction challenges, and Orbit Sketch has three equal-group charts. Only correct, unassisted checks prepare the ship. Then a separate final launch check needs all twelve facts right in a row, in a fresh shuffled order. A wrong answer offers a new shuffled attempt and keeps completed modules. A new launch is available each calendar day; module recaps remain available at any time.</p><h3>Character rewards are different</h3><p>Trying different fact/activity combinations earns customisation badges, even when an answer needs another go. Repeating the same combination does not repeatedly earn creation points. Cosmo Hop and Fleet Flight Check use all selected tables and earn practice credit; they do not complete an individual rocket’s systems.</p><h3>Table read-alouds</h3><p>My progress reads each complete table and highlights its current line. Press the same button to stop. Songs are planned for a later update.</p></section><section class="choice-card"><h2>A fresh creation mission</h2><p>Start a new grey blob and a new fleet to prepare. Keep learned facts, Cosmo Hop records, owned clothes, sparks and completed flight records.</p><button class="secondary" id="new-mission">Start a new creation mission →</button><h3>Try the launch scene</h3><p>A labelled preview for Rocket ${p().activeRocket}. This changes no readiness, badges or Starbase access.</p><button class="secondary" id="preview-launch">Preview Rocket ${p().activeRocket} launching ↟</button><h3>The Starbase</h3><p>A real, completed rocket launch opens Meteor Dash and Constellation Pairs. These games are just for fun and do not earn learning badges or ship checks.</p><h3>Saved separately on each device</h3><p>Two explorers keep their own progress, rockets and characters in this browser. There is no device sync. Clearing website data removes its saved progress.</p></section></div>`;}

function launchPage(){const table=flight.table,complete=flight.phase==='complete';return `<section class="launch-page phase-${flight.phase}">${flight.preview?'<div class="preview-banner">LAUNCH PREVIEW · NO LEARNING PROGRESS CHANGED</div>':''}<span class="eyebrow">${complete?'ANOTHER LITTLE CREW IS HOME':'ROCKET '+table+' · THE '+table+' TIMES TABLE'}</span><h1>${complete?'You got them home.':'Let’s get this crew home!'}</h1><p>${complete?flight.newGame?'New Starbase game unlocked: '+esc(flight.newGame)+'!':'All five systems. One very proud Multiploid.':'Fuel, cargo, bridge, shields and route: ready for lift-off.'}</p><div class="launch-theatre">${starsArt()}<div class="home-planet">${planetArt('planet','#a1d7c1')}</div><div class="launch-pad" aria-hidden="true"></div><div class="launch-smoke" aria-hidden="true">${Array.from({length:10},(_,i)=>`<i style="--cloud:${i}"></i>`).join('')}</div><div class="launch-speed-lines" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i style="--trail:${i}"></i>`).join('')}</div><div class="launching-rocket">${rocketArt(table,{percent:100,launched:complete})}<span class="launch-exhaust" aria-hidden="true"></span></div><div class="launch-count" id="launch-count">${flight.phase==='ignition'?'Engines on!':flight.phase==='lift'?'Lift-off!':flight.phase==='cruise'?'Next stop: home!':'Home safe ✓'}</div></div>${complete?`<div class="button-row"><button class="primary" data-go="home">Back to Mission Control →</button>${!flight.preview?'<button class="secondary" data-go="starbase">The Starbase is open ✦</button>':''}</div>`:'<p class="launch-cheer">Your number skills made this happen.</p>'}</section>`;}
function starbasePage(){const unlocked=availableGames(p());return `<section class="page-intro"><div><span class="eyebrow">TWO FREE GAMES · A NEW GAME FOR EACH DIFFERENT ROCKET HOME</span><h1>Welcome to the Starbase.</h1><p>${unlocked.length} games ready. Daily relaunches keep your learning fresh; new rockets grow your games collection.</p></div><button class="secondary" data-go="home">Mission Control →</button></section><div class="starbase-grid">${GAMES.map((g,i)=>`<button class="arcade-card ${i<unlocked.length?'':'game-locked'}" data-arcade="${g.id}" ${i>=unlocked.length?'disabled':''}><div class="arcade-art">${planetArt(g.art,g.colour)}</div><span class="eyebrow">${i<2?'FREE TO PLAY':i<unlocked.length?'ROCKET REWARD ✓':'BRING '+(i-1)+' DIFFERENT ROCKET'+(i===2?'':'S')+' HOME'}</span><h2>${g.name}</h2><p>${g.description}</p><strong>${i<unlocked.length?'Play →':'Locked · keep helping the crew'}</strong></button>`).join('')}</div>`;}

function arcadePage(){return `<div class="game-top"><button class="text-button" data-go="starbase">← The Starbase</button><span>${GAMES.find(g=>g.id===arcadeMode)?.name||'Starbase'}</span><button class="small-button" id="restart-arcade">Play again ↻</button></div><section class="arcade-room">${arcadeMode==='meteor'?'<canvas id="meteor-canvas" tabindex="0" aria-label="Steer with your finger or the left and right arrows. Collect stars and avoid meteors."></canvas><div class="arcade-controls"><p>Drag to steer, or use ← →. Three shields. No maths—just play.</p><button class="secondary" id="pause-arcade">Pause / Resume</button></div><p id="arcade-result" role="status"></p>':arcadeMode==='pairs'?'<div id="constellation-game"></div><p id="arcade-result" role="status"></p>':`<div class="bonus-copilot">${creature(p())}</div><div id="bonus-game"></div><p id="arcade-result" role="status"></p>`}</section>`;}

function modalMarkup(){if(!modal)return '';if(modal.type==='setup'){const preview={...p(),species:draft.species,voiceStyle:draft.voice};return `<dialog id="modal" class="setup-dialog"><button class="close-dialog" id="close-modal" aria-label="Close">×</button><span class="eyebrow">BADGE 1 · JUST FOR HAVING A GO</span><h1>There you are.</h1><p>A name. A shape. A little personality.</p><div class="setup-grid"><div class="setup-preview">${creature(preview)}</div><div><label for="pal-name">My Multiploid’s name</label><input id="pal-name" maxlength="20" placeholder="What shall we call them?" value="${esc(draft.name)}"><h3>A shape to call your own</h3><div class="shape-options">${['orbit','comet','lunar'].map(s=>`<button data-shape="${s}" class="${draft.species===s?'selected':''}">${s[0].toUpperCase()+s.slice(1)}</button>`).join('')}</div><h3>Give me a voice</h3><div class="voice-options">${[['heart2','Heart 2'],['mallow','Little monster']].map(([v,label])=>`<button data-voice="${v}" class="${draft.voice===v?'selected':''}"><span>${label}</span><small>♫ Hear me</small></button>`).join('')}</div><p class="hint">Keep these for this mission. Make someone new next time.</p><button class="primary" id="confirm-identity" ${!draft.name.trim()?'disabled':''}>Let’s go together →</button></div></div></dialog>`;}return `<dialog id="modal" class="small-dialog"><button class="close-dialog" id="close-modal" aria-label="Close">×</button><span class="eyebrow">GROWN-UPS</span><h2>${modal.type==='reset'?'Ready for a new little beginning?':'A quick grown-up check'}</h2><p>${modal.type==='reset'?'This character will join the mission album. Learning progress and records stay saved.':'What is 12 + 17?'}</p>${modal.type==='gate'?'<input id="gate-answer" inputmode="numeric" aria-label="Answer to 12 plus 17"><button class="primary" id="unlock-grownups">Open grown-ups →</button>':'<button class="primary" id="confirm-reset">Start the next mission →</button>'}<p id="modal-feedback" role="status"></p></dialog>`;}
function render(){renderedDay=localDay();clearTimeout(advanceTimer);const old=document.querySelector('.live-creature'),oldKey=old?.dataset.creatureKey,oldView=document.body.dataset.view,markup=(view==='game'?game():view==='workshop'?workshop():view==='progress'?progress():view==='grownups'?grownups():view==='launch'?launchPage():view==='starbase'?starbasePage():view==='arcade'?arcadePage():home());cleanManip?.();cleanManip=null;orbitEditor=null;cleanArcade?.();cleanArcade=null;cleanGestures?.();const preserve=old&&!modal&&!document.querySelector('dialog')&&oldView===view&&!markup.includes('setup-preview')&&markup.includes('data-creature-key="'+esc(oldKey)+'"');if(preserve)old.remove();else{cleanModels?.();cleanModels=null;}document.body.dataset.view=view;$('#app').innerHTML=header()+`<main>${markup}</main><footer><span>made for little explorers</span><b>multiploids <i>×</i></b><span>free to play · saved on this device</span><button class="text-button footer-grownups" data-go="grownups">Grown-ups ↗</button></footer>`+modalMarkup();if(preserve){const next=document.querySelector('.live-creature');if(next?.dataset.creatureKey===oldKey)next.replaceWith(old);else{cleanModels?.();cleanModels=null;}}if(!cleanModels)cleanModels=mountMonsters();cleanGestures=bindPalInteractions();setSound(state.sound);setCharacterVoice(p().voiceStyle);soundEnabled(state.sound);bind();bindSpace();if(modal){$('#modal').showModal();$('#modal').oncancel=e=>{e.preventDefault();modal=null;render();};}if(view==='game'&&session?.busy&&!session.finished){if(session.mode==='skyhop')armAdvance(session.run.ended?1700:1200,()=>{if(session.run.ended){session.finished=true;render();}else{nextRunFact(session.run);session.answer='';session.busy=false;session.feedback='';render();sayFact(fact(),'skyhop',p().voiceStyle);}});else if(session.mode==='launchcheck'&&session.launchCheck.complete)armAdvance(700,()=>beginLaunchSignalChase());else armAdvance(1400,advancePractice);}}
function navigate(next){stopReading();clearTimeout(launchTimer);clearInterval(launchInterval);if(next==='grownups'){modal={type:'gate'};render();return;}if(view==='game'&&!session?.finished&&next==='workshop'){session.paused=true;}else if(view==='game'&&next!=='workshop')session=null;if(next==='home'||next==='starbase')session=null;clearTimeout(advanceTimer);stopVoice();view=next;tablePicker=false;draft={};modal=null;render();scrollTo({top:0,behavior:'smooth'});}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=e=>{e.preventDefault();navigate(b.dataset.go);});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>begin(b.dataset.start));$('#make-creature')?.addEventListener('click',()=>p().mission.locks.identity?navigate('workshop'):openSetup());$('#sound').onclick=()=>{stopReading();state.sound=!state.sound;save();setSound(state.sound);soundEnabled(state.sound);$('#sound').textContent=state.sound?'♫':'♫̸';$('#sound').setAttribute('aria-label',(state.sound?'Mute':'Enable')+' sounds');};$('#profile').onchange=e=>{stopReading();clearTimeout(launchTimer);clearInterval(launchInterval);state.active=Number(e.target.value);ensureFleet(p());session=null;modal=null;draft={};view='home';stopVoice();save();render();};$('#choose-tables')?.addEventListener('click',()=>{if(view!=='home'){navigate('home');tablePicker=true;}else tablePicker=!tablePicker;render();});$('#close-tables')?.addEventListener('click',()=>{tablePicker=false;render();});document.querySelectorAll('[data-table]').forEach(b=>b.onclick=()=>{const table=Number(b.dataset.table),tables=p().tables.includes(table)?p().tables.filter(t=>t!==table):[...p().tables,table];try{changeTables(p(),tables);ensureFleet(p());save();render();}catch(e){toast(e.message);}});
 document.querySelectorAll('[data-digit]').forEach(b=>b.onclick=()=>digit(b.dataset.digit));$('#check-answer')?.addEventListener('click',submit);$('#hear-question')?.addEventListener('click',()=>sayFact(fact(),session.mode,p().voiceStyle));$('#leave-game')?.addEventListener('click',()=>navigate('home'));$('#resume-round')?.addEventListener('click',()=>{if(!session?.paused)return;session.paused=false;view='game';render();if(!session.busy&&!session.finished)sayFact(fact(),session.mode,p().voiceStyle);});$('#skip')?.addEventListener('click',()=>{if(!session.busy)advancePractice();});$('#hint')?.addEventListener('click',()=>{if(session.busy)return;session.assisted=true;session.shownGroups=fact().a;session.feedback=session.mode==='bridge'?'Think of '+fact().b+' groups of '+fact().a+'.':fact().a+' groups of '+fact().b+' make '+fact().total+'.';render();});document.querySelectorAll('[data-crate]').forEach(b=>b.onclick=()=>{session.shownGroups=Math.min(fact().a,Math.max(session.shownGroups,Number(b.dataset.crate)+1));render();});
 $('#close-modal')?.addEventListener('click',()=>{modal=null;render();});$('#pal-name')?.addEventListener('input',e=>{draft.name=e.target.value;$('#confirm-identity').disabled=!draft.name.trim();});document.querySelectorAll('[data-shape]').forEach(b=>b.onclick=()=>{draft.species=b.dataset.shape;render();});document.querySelectorAll('[data-voice]').forEach(b=>b.onclick=()=>{draft.voice=b.dataset.voice;render();say(['hello'],draft.voice);});$('#confirm-identity')?.addEventListener('click',()=>{try{const mode=modal.mode;confirmIdentity(p(),{name:draft.name,species:draft.species,voice:draft.voice});save();modal=null;draft={};if(mode)begin(mode);else{view='workshop';render();}soundEffect('celebrate');}catch(e){toast(e.message);}});
 document.querySelectorAll('[data-preview-colour]').forEach(b=>b.onclick=()=>{draft.colour=b.dataset.previewColour;render();});$('#confirm-colour')?.addEventListener('click',()=>{if(chooseFeature(p(),'colour',draft.colour)){draft={};save();render();soundEffect('celebrate');}});document.querySelectorAll('[data-preview-antennae]').forEach(b=>b.onclick=()=>{draft.antennae=b.dataset.previewAntennae;render();});$('#confirm-antennae')?.addEventListener('click',()=>{if(chooseFeature(p(),'antennae',draft.antennae)){draft={};save();render();soundEffect('celebrate');}});document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{if(claimClothes(p(),b.dataset.category,b.dataset.claim)){save();render();soundEffect('celebrate');}});document.querySelectorAll('[data-eye]').forEach(b=>b.onclick=()=>{if(p().species==='blob'){toast('Choose your shape first.');return;}p().eyeColour=b.dataset.eye;save();render();});document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{if(equipItem(p(),b.dataset.category,b.dataset.equip==='none'?null:b.dataset.equip)){save();render();}});document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{if(buyItem(p(),b.dataset.buy)){save();render();soundEffect('celebrate');}});$('#dance')?.addEventListener('click',()=>document.querySelector('[data-pal-action="dance"]')?.click());
 $('#unlock-grownups')?.addEventListener('click',()=>{if($('#gate-answer').value.trim()==='29'){modal=null;view='grownups';render();}else $('#modal-feedback').textContent='Try that little sum again.';});$('#save-name')?.addEventListener('click',()=>{p().name=$('#explorer-name').value.trim()||'Explorer';save();render();toast('Explorer name saved.');});$('#new-mission')?.addEventListener('click',()=>{modal={type:'reset'};render();});$('#confirm-reset')?.addEventListener('click',()=>{resetMission(p());save();session=null;modal=null;draft={};view='home';render();toast('A new little beginning. Your learning and records are safe.');});
}
function stopReading(){readToken++;activeReadTable=null;stopVoice();document.querySelectorAll('[data-read-table]').forEach(b=>{b.textContent='♫ Read this table';b.setAttribute('aria-pressed','false');});document.querySelectorAll('.reading-fact').forEach(e=>e.classList.remove('reading-fact'));}
async function readTable(table){if(activeReadTable===table){stopReading();return;}if(!state.sound){toast('Turn sound on with the music button to hear your table.');return;}stopReading();activeReadTable=table;const token=readToken,button=document.querySelector('[data-read-table="'+table+'"]');if(button){button.textContent='■ Stop reading';button.setAttribute('aria-pressed','true');}const parts=factsFor([table]).flatMap((f,i)=>[{key:String(f.a),row:f.b},'times',String(f.b),'equals',String(f.total),{pause:600}]);await say(parts,p().voiceStyle,{onStep:part=>{if(token!==readToken||!part?.row)return;document.querySelectorAll('.reading-fact').forEach(e=>e.classList.remove('reading-fact'));document.querySelector('[data-read-fact="'+table+':'+part.row+'"]')?.classList.add('reading-fact');}});if(token===readToken)stopReading();}
function beginLaunchSignalChase(){if(view!=='game'||!session?.launchCheck?.complete)return;const stage=$('.launch-check-stage');if(!stage)return;stage.classList.remove('launch-lights-top');stage.classList.add('launch-lights-chase');session.feedback='All systems go. Your crew is ready!';$('#answer-feedback').textContent=session.feedback;armAdvance(1300,()=>beginLaunch(false));}
function beginLaunch(preview=false){const table=p().activeRocket;if(!preview){const status=rocketStatus(p(),table);if(!status.ready){toast('Finish all five systems first.');return;}if(status.launchedToday){toast('Rocket '+table+' has flown today. You can recap its modules and launch again tomorrow.');return;}if(!hasLaunchProof(p(),table)){begin('launchcheck');return;}}stopReading();clearTimeout(advanceTimer);clearInterval(launchInterval);clearTimeout(launchTimer);const current=flight={table,preview,phase:'ignition'};view='launch';modal=null;render();scrollTo({top:0,behavior:'instant'});if(state.sound)soundEffect('travel');launchTimer=setTimeout(()=>{if(view!=='launch'||flight!==current)return;flight.phase='lift';render();launchTimer=setTimeout(()=>{if(view!=='launch'||flight!==current)return;flight.phase='cruise';render();launchTimer=setTimeout(()=>{if(view!=='launch'||flight!==current)return;if(!flight.preview){const before=availableGames(p()).length;launchRocket(p(),flight.table);const after=availableGames(p());flight.newGame=after.length>before?after.at(-1).name:null;save();}flight.phase='complete';render();if(state.sound)soundEffect('celebrate');},950);},3100);},1100);}

function submitLaunchCheck(answer){const f=fact();recordPractice(p(),f,'launchcheck',{correct:Number(answer)===f.total});const result=scoreLaunchCheck(p(),session.launchCheck,answer);save();if(!result.correct){session.failedFact=f;session.finished=true;render();return;}if(result.complete){session.busy=true;session.feedback='All twelve launch lamps on. Lift-off!';render();return;}session.index=session.launchCheck.index;session.answer='';session.feedback=result.streak+' launch lights on. Keep going!';render();if(state.sound)soundEffect('celebrate');sayFact(fact(),'launchcheck',p().voiceStyle);}
function submitCheck(answer,skip=false){if(!session||session.mode!=='test'||session.finished)return;const f=fact();if(!skip){recordPractice(p(),f,'test',{correct:Number(answer)===f.total});save();}session.check.answers.push(answer);session.index++;session.answer='';session.feedback='';if(session.index>=session.deck.length){session.checkResult=markCheck(session.check);p().checkHistory.unshift(session.checkResult);p().checkHistory=p().checkHistory.slice(0,20);session.finished=true;save();render();if(state.sound)soundEffect('celebrate');}else{render();sayFact(fact(),'test',p().voiceStyle);}}
function bindSpace(){
 $('#toggle-fleet')?.addEventListener('click',()=>{fleetExpanded=!fleetExpanded;render();});document.querySelectorAll('[data-rocket]').forEach(b=>b.onclick=()=>{stopReading();p().activeRocket=Number(b.dataset.rocket);save();render();});$('#launch-rocket')?.addEventListener('click',()=>beginLaunch(false));$('#replay-launch')?.addEventListener('click',()=>beginLaunch(true));$('#preview-launch')?.addEventListener('click',()=>beginLaunch(true));document.querySelectorAll('[data-read-table]').forEach(b=>b.onclick=()=>readTable(Number(b.dataset.readTable)));$('#skip-test')?.addEventListener('click',()=>submitCheck('—',true));
 if(view==='game'&&session&&!session.finished&&session.mode==='arrays'){const source=$('#star-row-source'),target=$('#array-target');if(source&&target)cleanManip=bindRowBuilder(source,target,()=>{if(session.busy||session.rows>=fact().b+2)return;session.rows++;render();});document.querySelectorAll('[data-remove-row]').forEach(b=>b.onclick=()=>{if(!session.busy&&session.rows){session.rows--;render();}});$('#clear-rows')?.addEventListener('click',()=>{if(!session.busy){session.rows=0;render();}});}
 if(view==='game'&&session&&!session.finished&&session.mode==='draw'&&$('#orbit-canvas')){const f=fact();orbitEditor=bindOrbitDrawing($('#orbit-canvas'),session,f,()=>{const count=$('#draw-counts');if(count)count.textContent=Array.from({length:f.b},(_,i)=>'Orbit '+(i+1)+': '+session.marks.filter(m=>m.group===i).length+'/'+f.a).join(' · ');});cleanManip=()=>orbitEditor?.dispose();document.querySelectorAll('[data-draw-tool]').forEach(b=>b.onclick=()=>{session.drawTool=b.dataset.drawTool;document.querySelectorAll('[data-draw-tool]').forEach(t=>t.classList.toggle('selected',t===b));});document.querySelectorAll('[data-orbit-add]').forEach(b=>b.onclick=()=>orbitEditor.add(Number(b.dataset.orbitAdd)));document.querySelectorAll('[data-orbit-remove]').forEach(b=>b.onclick=()=>orbitEditor.remove(Number(b.dataset.orbitRemove)));$('#clear-orbits')?.addEventListener('click',()=>{if(!session.busy){session.marks=[];session.paths=[];orbitEditor.redraw();$('#draw-counts').textContent='A fresh star chart. Place your equal groups.';}});}
 document.querySelectorAll('[data-arcade]').forEach(b=>b.onclick=()=>{if(!availableGames(p()).some(g=>g.id===b.dataset.arcade))return;arcadeMode=b.dataset.arcade;view='arcade';stopReading();render();});$('#restart-arcade')?.addEventListener('click',()=>render());if(view==='arcade'){if(arcadeMode==='meteor'&&$('#meteor-canvas')){const game=mountMeteorDash($('#meteor-canvas'),p(),result=>{p().arcadeRecords.meteor=Math.max(p().arcadeRecords.meteor||0,result.score);save();showArcadeResult(result.score+' stars collected · Best '+p().arcadeRecords.meteor+'.');});cleanArcade=()=>game.dispose();$('#pause-arcade').onclick=()=>game.pause();}else if(arcadeMode==='pairs'&&$('#constellation-game'))cleanArcade=mountConstellation($('#constellation-game'),result=>{const old=p().arcadeRecords.pairs;p().arcadeRecords.pairs=old?Math.min(old,result.moves):result.moves;save();showArcadeResult('Every space friend found! '+result.moves+' turns · Best '+p().arcadeRecords.pairs+'.');if(state.sound)soundEffect('celebrate');});else if($('#bonus-game'))cleanArcade=mountBonusGame($('#bonus-game'),arcadeMode,p(),showArcadeResult);}
}

document.addEventListener('keydown',e=>{if(view!=='game'||modal||session?.finished||e.target.matches('select,textarea')||e.target.closest('[data-pal]'))return;if(/^\d$/.test(e.key)){e.preventDefault();digit(e.key);}else if(e.key==='Backspace'){e.preventDefault();digit('back');}else if(e.key==='Enter'){e.preventDefault();submit();}});
window.addEventListener('focus',()=>{if(view==='home'&&renderedDay!==localDay())render();});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&view==='home'&&renderedDay!==localDay())render();});
save();render();if(location.protocol!=='capacitor:'&&'serviceWorker'in navigator&&globalThis.isSecureContext)navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;offlineReady=true;$('#offline-status')?.replaceChildren(document.createTextNode('✓ Ready offline'));}).catch(()=>{});

function showArcadeResult(message){const host=$('#arcade-result');if(!host)return;host.className='arcade-result-panel';host.innerHTML='<h2>Another adventure?</h2><p>'+esc(message)+'</p><div class="button-row"><button class="primary" id="result-replay">Play again ↻</button><button class="secondary" id="result-return">Return to Starbase →</button></div>';$('#result-replay').onclick=()=>render();$('#result-return').onclick=()=>navigate('starbase');$('#result-replay').focus({preventScroll:true});}

document.addEventListener('click',e=>{if(e.target.closest('#claim-weekly-suit')&&claimWeeklySuit(p())){save();soundEffect('celebrate');render();toast('New space suit earned! It is yours to keep.');}});
